package netdiag

import (
	"context"
	"fmt"
	"log"
	"net"
	"net/netip"
	"time"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/nettrace"
)

// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
// resolved message and the done message. The producer therefore never waits
// for a reader.
const pathChanCap = nettrace.MaxHopsLimit + 2

// pathEngine is the seam between the path tab and the network: tests replace
// it with a fake.
type pathEngine struct {
	supported func() error
	resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
	trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
}

// systemPathEngine returns the engine backed by the real resolver and sockets.
func systemPathEngine() pathEngine {
	return pathEngine{
		supported: nettrace.Supported,
		resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
			return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
		},
		trace: nettrace.TraceEach,
	}
}

// pathResolvedMsg reports the address the target resolved to.
type pathResolvedMsg struct {
	gen  int
	addr netip.Addr
}

// pathHopMsg carries one hop as the engine reports it.
type pathHopMsg struct {
	gen int
	hop nettrace.Hop
}

// pathDoneMsg ends a run: a result, or an error when no trace happened.
type pathDoneMsg struct {
	gen    int
	result nettrace.Result
	err    error
}

// producePath resolves the target, traces it and sends the messages to out,
// then closes out. It runs inside a Cmd and touches no model (Rule 110).
// out must have room for pathChanCap messages: sends never block, so a view
// that stops reading after canceling leaks nothing.
func producePath(ctx context.Context, gen int, tg pathTarget, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
	defer close(out)
	send := func(m tea.Msg) {
		select {
		case out <- m:
		default:
		}
	}
	// sendDone must never be lost: when the channel is full the oldest message
	// is dropped to make room. The producer is the only sender, so one drop
	// frees a slot for good.
	sendDone := func(m tea.Msg) {
		for range 2 {
			select {
			case out <- m:
				return
			default:
			}
			select {
			case <-out:
			default:
			}
		}
	}

	addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
	if err != nil {
		if ctx.Err() == nil { // esc during the resolution is not an error
			log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
		}
		sendDone(pathDoneMsg{gen: gen, err: err})
		return
	}
	send(pathResolvedMsg{gen: gen, addr: addr})

	res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
		send(pathHopMsg{gen: gen, hop: h})
	})
	if err != nil {
		log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
	}
	sendDone(pathDoneMsg{gen: gen, result: res, err: err})
}

// resolvePathTarget returns the IPv4 address to trace: a literal is used as
// is, a name is resolved under its own timeout.
func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
	if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
		return a, nil
	}
	rctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	addrs, err := e.resolve(rctx, host)
	if err != nil {
		return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
	}
	if len(addrs) == 0 {
		return netip.Addr{}, errPathNoIPv4
	}
	return addrs[0], nil
}

// waitForPathMsg returns a Cmd that yields the next message of in, or nil
// once in is closed. The view re-arms it after every message.
func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
	return func() tea.Msg {
		m, ok := <-in
		if !ok {
			return nil
		}
		return m
	}
}

package netdiag

import (
	"context"
	"net/netip"
	"time"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/nettrace"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// reasonPathUnsupported is shown when the platform cannot trace a path. The
	// header greys enter out and the handler refuses with the same text.
	reasonPathUnsupported = "The path trace is not supported on this platform"

	// defaultPathResolveTimeout bounds the name resolution of a target.
	defaultPathResolveTimeout = 5 * time.Second

	// pathInputCharLimit holds a 253-character host name, a colon and a port.
	pathInputCharLimit = 262
)

// pathState is where the Path tab is in its life cycle.
type pathState int

const (
	// pathEditing: the target field has the keyboard.
	pathEditing pathState = iota
	// pathRunning: a trace is in flight; the field is blurred.
	pathRunning
	// pathDone: a trace ended (or was canceled); the hops stay on screen.
	pathDone
)

// PathModel is the Path tab: a target field above a table of hops that fills
// in while the trace runs.
type PathModel struct {
	width int

	engine         pathEngine
	resolveTimeout time.Duration

	input textinput.Model
	table datatable.Model[nettrace.Hop]

	state  pathState
	target pathTarget
	addr   netip.Addr
	// hops is what the engine reported so far; the table shows
	// visiblePathHops(hops). At done it is replaced by Result.Hops.
	hops   []nettrace.Hop
	result *nettrace.Result
	// errText is the persistent footer error of a run that never traced. It is
	// cleared by a change of the field or by the next launch, not by a timer.
	errText string

	// gen identifies the run whose messages are accepted; cancel and msgs
	// belong to that run.
	gen    int
	cancel context.CancelFunc
	msgs   <-chan tea.Msg

	footer components.FooterMessage
}

func newPathModel(e pathEngine) *PathModel {
	in := textinput.New()
	theme.StyleTextInput(&in)
	in.Placeholder = "hostname or IPv4 address[:port]"
	in.CharLimit = pathInputCharLimit
	in.Focus()

	return &PathModel{
		engine:         e,
		resolveTimeout: defaultPathResolveTimeout,
		input:          in,
		table: datatable.New(datatable.Config[nettrace.Hop]{
			Columns:    pathColumns(),
			SortColumn: -1, // the path order is the content
		}),
	}
}

// InEditMode reports whether the target field has the keyboard.
func (pm *PathModel) InEditMode() bool { return pm.state == pathEditing }

func (pm *PathModel) running() bool { return pm.state == pathRunning }

func (pm *PathModel) resize(width, height int) {
	pm.width = width
	pm.input.SetWidth(max(width-ansi.StringWidth(pathBarLabel)-4, 10))
	pm.table.Resize(width, max(height, 3))
}

// launchable is the one answer to "can a trace start here", read by the header
// and by the handler (Rule 130).
func (pm *PathModel) launchable() shortcut.Availability {
	if pm.engine.supported() != nil {
		return shortcut.Unavailable(reasonPathUnsupported)
	}
	return shortcut.Availability{}
}

func (pm *PathModel) update(msg tea.Msg) (*PathModel, tea.Cmd) {
	switch msg := msg.(type) {
	case pathResolvedMsg:
		return pm.handleResolved(msg)
	case pathHopMsg:
		return pm.handleHop(msg)
	case pathDoneMsg:
		return pm.handleDone(msg)
	case tea.KeyPressMsg:
		return pm.handleKey(msg)
	case tea.PasteMsg:
		return pm.handlePaste(msg)
	}
	// Anything else is a footer expiry or the cursor blink of the field: the
	// field needs the blink itself, or its cursor freezes.
	pm.footer.Handle(msg)
	var cmd tea.Cmd
	pm.input, cmd = pm.input.Update(msg)
	return pm, cmd
}

func (pm *PathModel) handleResolved(msg pathResolvedMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.addr = msg.addr
	return pm, waitForPathMsg(pm.msgs)
}

func (pm *PathModel) handleHop(msg pathHopMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.hops = append(pm.hops, msg.hop)
	pm.table.SetItems(visiblePathHops(pm.hops))
	return pm, waitForPathMsg(pm.msgs)
}

func (pm *PathModel) handleDone(msg pathDoneMsg) (*PathModel, tea.Cmd) {
	if msg.gen != pm.gen {
		return pm, nil
	}
	pm.releaseRun()
	if msg.err != nil {
		pm.hops = nil
		pm.table.SetItems(nil)
		pm.errText = pathErrorLabel(pm.target.Host, msg.err)
		pm.state = pathEditing
		return pm, pm.input.Focus()
	}
	res := msg.result
	pm.result = &res
	pm.hops = res.Hops
	pm.table.SetItems(visiblePathHops(res.Hops))
	pm.state = pathDone
	return pm, nil
}

// releaseRun cancels the run's context (releasing it) and forgets its channel.
func (pm *PathModel) releaseRun() {
	if pm.cancel != nil {
		pm.cancel()
		pm.cancel = nil
	}
	pm.msgs = nil
}

func isPathNavKey(key string) bool {
	switch key {
	case "up", "down", "pgup", "pgdown", "home", "end":
		return true
	}
	return false
}

func (pm *PathModel) handleKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
	key := msg.String()
	if isPathNavKey(key) {
		return pm, pm.table.Update(msg)
	}
	switch pm.state {
	case pathEditing:
		return pm.handleEditKey(msg)
	case pathRunning:
		if key == "esc" {
			return pm.cancelRun()
		}
	case pathDone:
		switch key {
		case "enter":
			return pm.launch(pm.target)
		case "esc":
			pm.state = pathEditing
			return pm, pm.input.Focus()
		}
	}
	return pm, nil
}

func (pm *PathModel) handleEditKey(msg tea.KeyPressMsg) (*PathModel, tea.Cmd) {
	switch msg.String() {
	case "enter":
		return pm.launchFromInput()
	case "esc", "tab", "shift+tab":
		return pm, nil
	}
	return pm.updateInput(msg)
}

func (pm *PathModel) handlePaste(msg tea.PasteMsg) (*PathModel, tea.Cmd) {
	if pm.state != pathEditing {
		return pm, nil // a paste reaches the focused field only (Rule 111)
	}
	return pm.updateInput(msg)
}

// updateInput hands msg to the field; a changed value drops the stale error.
func (pm *PathModel) updateInput(msg tea.Msg) (*PathModel, tea.Cmd) {
	before := pm.input.Value()
	var cmd tea.Cmd
	pm.input, cmd = pm.input.Update(msg)
	if pm.input.Value() != before {
		pm.errText = ""
	}
	return pm, cmd
}

func (pm *PathModel) launchFromInput() (*PathModel, tea.Cmd) {
	tg, err := parsePathTarget(pm.input.Value())
	if err != nil {
		return pm, pm.footer.Error(capitalize(err.Error()))
	}
	return pm.launch(tg)
}

// launch starts a run: the model changes here, in Update; the Cmd only does I/O.
func (pm *PathModel) launch(tg pathTarget) (*PathModel, tea.Cmd) {
	if a := pm.launchable(); !a.Enabled() {
		return pm, pm.footer.Warn(a.Reason)
	}
	pm.releaseRun()
	pm.gen++
	pm.target = tg
	pm.addr = netip.Addr{}
	pm.hops = nil
	pm.result = nil
	pm.errText = ""
	pm.footer.Clear()
	pm.table.SetItems(nil)

	ctx, cancel := context.WithCancel(context.Background())
	ch := make(chan tea.Msg, pathChanCap)
	pm.cancel, pm.msgs = cancel, ch
	pm.input.Blur()
	pm.state = pathRunning
	return pm, startPathRun(ctx, pm.gen, tg, pm.resolveTimeout, pm.engine, ch)
}

// cancelRun answers esc at once: the run's late messages are dropped by the
// generation bump, the hops already seen stay on screen.
func (pm *PathModel) cancelRun() (*PathModel, tea.Cmd) {
	pm.releaseRun()
	pm.gen++
	pm.result = &nettrace.Result{Outcome: nettrace.OutcomeCancelled}
	pm.state = pathDone
	return pm, nil
}

// startPathRun builds the launch Cmd from values only, so that no closure
// reads the model (Rule 110).
func startPathRun(ctx context.Context, gen int, tg pathTarget, timeout time.Duration, e pathEngine, ch chan tea.Msg) tea.Cmd {
	return tea.Batch(
		func() tea.Msg {
			producePath(ctx, gen, tg, timeout, e, ch)
			return nil
		},
		waitForPathMsg(ch),
	)
}

package netdiag

import (
	"errors"
	"fmt"
	"slices"
	"strconv"
	"strings"

	"github.com/anthnel/devdesk/internal/nettrace"
)

var (
	// errPathResolve marks a target name that could not be resolved.
	errPathResolve = errors.New("could not resolve the path target")
	// errPathNoIPv4 marks a target name that resolved to no IPv4 address.
	errPathNoIPv4 = errors.New("the path target has no IPv4 address")
	// errPathIPv6 is the validation message for a literal IPv6 target. It is
	// shown as is in the footer, hence the capital letter.
	errPathIPv6 = errors.New( //nolint:staticcheck // ST1005: user-facing text, same wording as pathErrorLabel
		"Only IPv4 targets are supported by the path trace")
)

// pathTarget is the validated input of the path trace. Port is optional (0 =
// none); it is shown but does not change the probes.
type pathTarget struct {
	Host string
	Port int
}

// String renders the target as typed: "host" or "host:port".
func (t pathTarget) String() string {
	if t.Port == 0 {
		return t.Host
	}
	return t.Host + ":" + strconv.Itoa(t.Port)
}

// parsePathTarget validates "host" or "host:port". IPv6 literals are refused.
func parsePathTarget(input string) (pathTarget, error) {
	s := strings.TrimSpace(input)
	if s == "" {
		return pathTarget{}, errors.New("target is required")
	}
	// Brackets or several colons can only be an IPv6 literal.
	if strings.Contains(s, "[") || strings.Count(s, ":") > 1 {
		return pathTarget{}, errPathIPv6
	}
	host, portText, hasPort := strings.Cut(s, ":")
	if err := validateTarget(host); err != nil {
		return pathTarget{}, err
	}
	if !hasPort {
		return pathTarget{Host: host}, nil
	}
	if err := validatePort(portText); err != nil {
		return pathTarget{}, err
	}
	port, _ := strconv.Atoi(portText) // validatePort accepted it
	return pathTarget{Host: host, Port: port}, nil
}

// visiblePathHops returns a new slice of the hops to display: sorted by TTL,
// unresolved hops dropped, everything above the first target or unreachable
// hop cut. The input is left untouched.
func visiblePathHops(hops []nettrace.Hop) []nettrace.Hop {
	sorted := slices.Clone(hops)
	slices.SortStableFunc(sorted, func(a, b nettrace.Hop) int { return a.TTL - b.TTL })
	out := make([]nettrace.Hop, 0, len(sorted))
	for _, h := range sorted {
		if h.Kind == nettrace.HopUnresolved {
			continue
		}
		out = append(out, h)
		if h.Kind == nettrace.HopTarget || h.Kind == nettrace.HopUnreachable {
			break
		}
	}
	return out
}

// pathErrorLabel maps a trace error to a fixed footer sentence. It never
// carries the raw error text (errno, resolver message).
func pathErrorLabel(host string, err error) string {
	switch {
	case errors.Is(err, errPathResolve):
		return "Could not resolve " + host + " — no probe was sent"
	case errors.Is(err, errPathNoIPv4):
		return host + " has no IPv4 address — the path trace is IPv4 only"
	case errors.Is(err, nettrace.ErrNotIPv4):
		return "Only IPv4 targets are supported by the path trace"
	case errors.Is(err, nettrace.ErrNotUnicast):
		return "The path trace needs a unicast address"
	case errors.Is(err, nettrace.ErrNoRoute):
		return "No route to " + host + " from this machine — no probe was sent"
	case errors.Is(err, nettrace.ErrUnsupported):
		return "The path trace is not supported on this platform"
	}
	return "The path trace failed — check logs"
}

// pathOutcomeLabel describes how a finished trace ended; N is the number of
// hops in the result.
func pathOutcomeLabel(res nettrace.Result) string {
	n := len(res.Hops)
	switch res.Outcome {
	case nettrace.OutcomeReached:
		return fmt.Sprintf("Reached at hop %d", n)
	case nettrace.OutcomeUnreachable:
		return fmt.Sprintf("Reported unreachable at hop %d", n)
	case nettrace.OutcomeMaxHops:
		return fmt.Sprintf("No answer from the target within %d hops", n)
	case nettrace.OutcomeDeadline:
		return fmt.Sprintf("Stopped after %d s", int(nettrace.DeadlineLimit.Seconds()))
	case nettrace.OutcomeCancelled:
		return "Canceled"
	}
	return "The path trace ended"
}

package netdiag

import (
	"log"
	"net/netip"

	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
)

const (
	// reasonNotARouteRow is the refusal of H off the Local route row. The header
	// greys the key out and the handler says the same thing at the footer.
	reasonNotARouteRow = "Select the Local route row to trace its path"

	// reasonPathBusy is shown on the Path footer when H lands on a running trace.
	reasonPathBusy = "A path trace is already running — esc cancels it"
)

// pathFromRoute is the one answer to "can H hand this row to the Path tab",
// read by the header and by the handler (Rule 130).
func (m *Model) pathFromRoute() shortcut.Availability {
	if c, ok := m.checksTable.Selected(); ok && c.ID == netcheck.CheckRoute {
		return shortcut.Availability{}
	}
	return shortcut.Unavailable(reasonNotARouteRow)
}

// tracePathFromRoute moves the results' target to the Path tab and leaves it
// editing: nothing is resolved or sent until the user presses enter there.
func (m *Model) tracePathFromRoute() (*Model, tea.Cmd) {
	if a := m.pathFromRoute(); !a.Enabled() {
		return m, m.footer.Warn(a.Reason)
	}
	if m.pathModel.running() {
		m.activeTab = tabPath
		return m, m.pathModel.footer.Warn(reasonPathBusy)
	}
	tg, err := m.buildTarget()
	if err != nil {
		log.Printf("ERROR [netdiag] target invalid on path hand-off: %v", err)
		return m, m.footer.Error("Cannot trace — the target is no longer valid")
	}
	m.activeTab = tabPath
	return m, m.pathModel.prefill(tg.Host)
}

// prefill puts host in the field and returns the tab to editing, dropping the
// outcome of an earlier trace.
func (pm *PathModel) prefill(host string) tea.Cmd {
	pm.state = pathEditing
	pm.target = pathTarget{}
	pm.addr = netip.Addr{}
	pm.hops = nil
	pm.result = nil
	pm.errText = ""
	pm.table.SetItems(nil)
	pm.input.SetValue(host)
	pm.input.CursorEnd()
	return pm.input.Focus()
}

