3	import (
4		"context"
5		"fmt"
6		"log"
7		"net"
8		"net/netip"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/nettrace"
14	)
15	
16	// pathChanCap holds a whole trace: every hop (at most MaxHopsLimit), the
17	// resolved message and the done message. The producer therefore never waits
18	// for a reader.
19	const pathChanCap = nettrace.MaxHopsLimit + 2
20	
21	// pathEngine is the seam between the path tab and the network: tests replace
22	// it with a fake.
23	type pathEngine struct {
24		supported func() error
25		resolve   func(ctx context.Context, host string) ([]netip.Addr, error)
26		trace     func(ctx context.Context, a netip.Addr, o nettrace.Options, onHop func(nettrace.Hop)) (nettrace.Result, error)
27	}
28	
29	// systemPathEngine returns the engine backed by the real resolver and sockets.
30	func systemPathEngine() pathEngine {
31		return pathEngine{
32			supported: nettrace.Supported,
33			resolve: func(ctx context.Context, host string) ([]netip.Addr, error) {
34				return net.DefaultResolver.LookupNetIP(ctx, "ip4", host)
35			},
36			trace: nettrace.TraceEach,
37		}
38	}
39	
40	// pathResolvedMsg reports the address the target resolved to.
41	type pathResolvedMsg struct {
42		gen  int
43		addr netip.Addr
44	}
45	
46	// pathHopMsg carries one hop as the engine reports it.
47	type pathHopMsg struct {
48		gen int
49		hop nettrace.Hop
50	}
51	
52	// pathDoneMsg ends a run: a result, or an error when no trace happened.
53	type pathDoneMsg struct {
54		gen    int
55		result nettrace.Result
56		err    error
57	}
58	
59	// producePath resolves the target, traces it and sends the messages to out,
60	// then closes out. It runs inside a Cmd and touches no model (Rule 110).
61	// out must have room for pathChanCap messages: sends never block, so a view
62	// that stops reading after canceling leaks nothing.
63	func producePath(ctx context.Context, gen int, tg pathTarget, resolveTimeout time.Duration, e pathEngine, out chan tea.Msg) {
64		defer close(out)
65		send := func(m tea.Msg) {
66			select {
67			case out <- m:
68			default:
69			}
70		}
71		// sendDone must never be lost: when the channel is full the oldest message
72		// is dropped to make room. The producer is the only sender, so one drop
73		// frees a slot for good.
74		sendDone := func(m tea.Msg) {
75			for range 2 {
76				select {
77				case out <- m:
78					return
79				default:
80				}
81				select {
82				case <-out:
83				default:
84				}
85			}
86		}
87	
88		addr, err := resolvePathTarget(ctx, tg.Host, resolveTimeout, e)
89		if err != nil {
90			if ctx.Err() == nil { // esc during the resolution is not an error
91				log.Printf("ERROR [netdiag/path] resolve %s: %v", tg.Host, err)
92			}
93			sendDone(pathDoneMsg{gen: gen, err: err})
94			return
95		}
96		send(pathResolvedMsg{gen: gen, addr: addr})
97	
98		res, err := e.trace(ctx, addr, nettrace.Options{}, func(h nettrace.Hop) {
99			send(pathHopMsg{gen: gen, hop: h})
100		})
101		if err != nil {
102			log.Printf("ERROR [netdiag/path] trace %s: %v", tg.Host, err)
103		}
104		sendDone(pathDoneMsg{gen: gen, result: res, err: err})
105	}
106	
107	// resolvePathTarget returns the IPv4 address to trace: a literal is used as
108	// is, a name is resolved under its own timeout.
109	func resolvePathTarget(ctx context.Context, host string, timeout time.Duration, e pathEngine) (netip.Addr, error) {
110		if a, err := netip.ParseAddr(host); err == nil && a.Is4() {
111			return a, nil
112		}
113		rctx, cancel := context.WithTimeout(ctx, timeout)
114		defer cancel()
115		addrs, err := e.resolve(rctx, host)
116		if err != nil {
117			return netip.Addr{}, fmt.Errorf("%w: %w", errPathResolve, err)
118		}
119		if len(addrs) == 0 {
120			return netip.Addr{}, errPathNoIPv4
121		}
122		return addrs[0], nil
123	}
124	
125	// waitForPathMsg returns a Cmd that yields the next message of in, or nil
126	// once in is closed. The view re-arms it after every message.
127	func waitForPathMsg(in <-chan tea.Msg) tea.Cmd {
128		return func() tea.Msg {
129			m, ok := <-in
130			if !ok {
131				return nil
132			}
133			return m
134		}
135	}
